	public function resize( $max_width, $max_height ) { $d = $this->dimensions(); $scale = min( 1, $max_width / $d['width'], $max_height / $d['height'] ); $w = max( 1, (int) round( $d['width'] * $scale ) ); $h = max( 1, (int) round( $d['height'] * $scale ) ); if ( $w === $d['width'] && $h === $d['height'] ) { return $this; } $new = $this->canvas( $w, $h ); imagecopyresampled( $new, $this->image, 0, 0, 0, 0, $w, $h, $d['width'], $d['height'] ); imagedestroy( $this->image ); $this->image = $new; return $this; }
