	public function configure( $options ) { if ( ! empty( $options['lossless'] ) ) { throw new RuntimeException( 'gd_lossless_not_guaranteed' ); } if ( ! empty( $options['preserve_icc'] ) ) { throw new RuntimeException( 'gd_icc_preservation_unavailable' ); } return $this; }
