	public function normalize_orientation() { if ( in_array( $this->orientation, array( 2, 4, 5, 7 ), true ) && function_exists( 'imageflip' ) ) { imageflip( $this->image, IMG_FLIP_HORIZONTAL ); } $angles = array( 3 => 180, 4 => 180, 5 => -90, 6 => -90, 7 => 90, 8 => 90 ); if ( isset( $angles[ $this->orientation ] ) ) { $rotated = imagerotate( $this->image, $angles[ $this->orientation ], 0 ); if ( $rotated ) { imagedestroy( $this->image ); $this->image = $rotated; } } $this->orientation = 1; return $this; }
